mapper.sql:
FROM USERS u LEFT JOIN ( SELECT user_idx, COUNT(*) AS social_count, GROUP_CONCAT(provider ORDER BY provider) AS linked_providers FROM USER_SOCIAL GROUP BY user_idx ) s ON u.user_idx = s.user_idx LEFT JOIN ( SELECT user_idx, MAX(login_at) AS last_login_at, SUBSTRING_INDEX(GROUP_CONCAT(login_method ORDER BY login_at DESC), ',', 1) AS last_login_method, SUM(CASE WHEN is_success = 1 THEN 1 ELSE 0 END) AS login_success_count, SUM(CASE WHEN is_success = 0 THEN 1 ELSE 0 END) AS login_fail_count FROM USER_LOGIN_HISTORY WHERE event_type = 'LOGIN' AND auth_type IN ('PASSWORD', 'SOCIAL') GROUP BY user_idx ) h ON u.user_idx = h.user_idx
AND u.account_status = #{status}
AND u.user_role = #{role}
AND s.user_idx IS NULL
AND FIND_IN_SET(#{provider}, IFNULL(s.linked_providers, '')) > 0
AND DATE(u.created_at) >= #{dateFrom}
AND DATE(u.created_at) <= #{dateTo}
AND u.user_id LIKE CONCAT('%', #{keyword}, '%')
AND u.nickname LIKE CONCAT('%', #{keyword}, '%')
AND u.user_email LIKE CONCAT('%', #{keyword}, '%')
AND ( u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') )

mapper.update:
UPDATE USERS
SET nickname = #{nickname},
    nationality = #{nationality},
    preferred_lang = #{preferredLang}
WHERE user_idx = #{userIdx}

mapper.select:
SELECT COUNT(*) > 0
FROM ADMIN_EFFECTIVE_PERMISSION_VW
WHERE user_idx = #{userIdx}
  AND permission_code = #{permissionCode}

SELECT baa.application_idx, baa.user_idx, baa.requested_role, baa.company_name, baa.business_number, baa.manager_name, baa.manager_phone, baa.description, baa.application_status, baa.reject_reason, baa.reviewed_by_user_idx, baa.reviewed_at, baa.created_at, baa.updated_at, u.user_id, u.nickname, u.user_email, u.user_role AS current_user_role, reviewer.nickname AS reviewer_nickname FROM BUSINESS_ACCOUNT_APPLICATION baa JOIN USERS u ON baa.user_idx = u.user_idx LEFT JOIN USERS reviewer ON baa.reviewed_by_user_idx = reviewer.user_idx
baa.application_status = #{status}
ORDER BY CASE baa.application_status WHEN 'PENDING' THEN 0 WHEN 'REJECTED' THEN 1 WHEN 'APPROVED' THEN 2 ELSE 3 END, baa.created_at DESC

SELECT *
FROM USER_LOGIN_HISTORY
WHERE user_idx = #{userIdx}
ORDER BY login_at DESC
LIMIT #{limit}

